.label {
  width: 200px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

sup {
  font-size: 75%;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
  top: -0.5em;
}

body {
  font-family: 'CustomWebFont', Arial, sans-serif;
  font-size-adjust: from-font;
}

.highlight {
  background: gold;
  padding: 4px 8px;
  border-radius: 4px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

const font = new FontFace('DynFont', 'url(dyn.woff2)');
font.load().then(loaded => {
  document.fonts.add(loaded);
});
